-- Boleteria: modelo Oracle compatible con entidades JPA del ZIP entregado.
-- Oracle XE 21c / 19c+ con columnas GENERATED BY DEFAULT ON NULL AS IDENTITY.
-- Ejecutar una sola vez en un esquema VACIO. No ejecuta DROP ni borra datos.
-- IMPORTANTE: el backend usa spring.jpa.hibernate.ddl-auto=update; se recomienda validate al ejecutar estos scripts.
-- La regla de no-solapamiento, aforo y expiracion se controla en el servicio Java.

CREATE TABLE MUNICIPIOS (
    ID_MUNICIPIO NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(100) NOT NULL,
    DEPARTAMENTO VARCHAR2(100) NOT NULL
);

CREATE TABLE TIPOS_PRESTADOR (
    ID_TIPO_PRESTADOR NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(100) NOT NULL
);

CREATE TABLE ROLES (
    ID_ROL NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(50) NOT NULL UNIQUE
);

CREATE TABLE USUARIOS_SISTEMA (
    ID_USUARIO NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    CORREO VARCHAR2(150) NOT NULL UNIQUE,
    CLAVE_HASH VARCHAR2(255) NOT NULL,
    ESTADO VARCHAR2(30) NOT NULL,
    ID_ROL NUMBER(19) NOT NULL,
    CONSTRAINT FK_USUARIOS_SIST_ID_ROL FOREIGN KEY (ID_ROL) REFERENCES ROLES(ID_ROL)
);

CREATE TABLE PRESTADORES (
    ID_PRESTADOR NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NIT VARCHAR2(30) NOT NULL UNIQUE,
    NOMBRE VARCHAR2(150) NOT NULL,
    CORREO VARCHAR2(150) NOT NULL,
    ID_MUNICIPIO NUMBER(19) NOT NULL,
    ID_TIPO_PRESTADOR NUMBER(19) NOT NULL,
    CONSTRAINT FK_PRESTADORES_ID_MUNICIPIO FOREIGN KEY (ID_MUNICIPIO) REFERENCES MUNICIPIOS(ID_MUNICIPIO),
    CONSTRAINT FK_PRESTADORES_ID_TIPO_PRES FOREIGN KEY (ID_TIPO_PRESTADOR) REFERENCES TIPOS_PRESTADOR(ID_TIPO_PRESTADOR)
);

CREATE TABLE PERFILES_CLIENTE (
    ID_PERFIL NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    DOCUMENTO VARCHAR2(30) NOT NULL UNIQUE,
    NOMBRE VARCHAR2(150) NOT NULL,
    TELEFONO VARCHAR2(30),
    ID_USUARIO NUMBER(19) NOT NULL UNIQUE,
    CONSTRAINT FK_PERFILES_CLIE_ID_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES USUARIOS_SISTEMA(ID_USUARIO)
);

CREATE TABLE PLANES (
    ID_PLAN NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(150) NOT NULL,
    DESCRIPCION VARCHAR2(1000),
    ESTADO VARCHAR2(30) NOT NULL,
    ID_PRESTADOR NUMBER(19) NOT NULL,
    CONSTRAINT FK_PLANES_ID_PRESTADOR FOREIGN KEY (ID_PRESTADOR) REFERENCES PRESTADORES(ID_PRESTADOR)
);

CREATE TABLE ATRACCIONES (
    ID_ATRACCION NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(150) NOT NULL,
    DESCRIPCION VARCHAR2(1000),
    ID_PRESTADOR NUMBER(19) NOT NULL,
    CONSTRAINT FK_ATRACCIONES_ID_PRESTADOR FOREIGN KEY (ID_PRESTADOR) REFERENCES PRESTADORES(ID_PRESTADOR)
);

CREATE TABLE FUNCIONES (
    ID_FUNCION NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    FECHA DATE NOT NULL,
    HORA_APERTURA INTERVAL DAY(0) TO SECOND(6) NOT NULL,
    HORA_CIERRE INTERVAL DAY(0) TO SECOND(6) NOT NULL,
    ESTADO VARCHAR2(30) NOT NULL,
    ID_ATRACCION NUMBER(19) NOT NULL,
    CONSTRAINT FK_FUNCIONES_ID_ATRACCION FOREIGN KEY (ID_ATRACCION) REFERENCES ATRACCIONES(ID_ATRACCION)
);

CREATE TABLE ZONAS (
    ID_ZONA NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(100) NOT NULL,
    AFORO NUMBER(10) NOT NULL,
    PRECIO NUMBER(12,2) NOT NULL,
    ID_FUNCION NUMBER(19) NOT NULL,
    CONSTRAINT FK_ZONAS_ID_FUNCION FOREIGN KEY (ID_FUNCION) REFERENCES FUNCIONES(ID_FUNCION)
);

CREATE TABLE TIPOS_ENTRADA (
    ID_TIPO_ENTRADA NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(100) NOT NULL,
    PORCENTAJE_DESCUENTO NUMBER(5,2) NOT NULL,
    REQUIERE_ADULTO NUMBER(1) NOT NULL,
    ES_ADULTO NUMBER(1)
);

CREATE TABLE COMBOS (
    ID_COMBO NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    NOMBRE VARCHAR2(150) NOT NULL,
    PRECIO NUMBER(12,2) NOT NULL,
    DIAS_VIGENCIA NUMBER(10) NOT NULL,
    ESTADO VARCHAR2(30) NOT NULL
);

CREATE TABLE COMBOS_ATRACCIONES (
    ID_COMBO NUMBER(19) NOT NULL,
    ID_ATRACCION NUMBER(19) NOT NULL,
    PORCENTAJE_PRECIO NUMBER(5,2) NOT NULL,
    CONSTRAINT PK_COMBOS_ATRACCIONES PRIMARY KEY (ID_COMBO, ID_ATRACCION),
    CONSTRAINT FK_COMBOS_ATRACC_ID_COMBO FOREIGN KEY (ID_COMBO) REFERENCES COMBOS(ID_COMBO),
    CONSTRAINT FK_COMBOS_ATRACC_ID_ATRACCION FOREIGN KEY (ID_ATRACCION) REFERENCES ATRACCIONES(ID_ATRACCION)
);

CREATE TABLE RESERVAS (
    ID_RESERVA NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    FECHA_HORA TIMESTAMP(6) NOT NULL,
    ESTADO VARCHAR2(30) NOT NULL,
    ID_PERFIL NUMBER(19) NOT NULL,
    ID_PLAN NUMBER(19),
    CONSTRAINT FK_RESERVAS_ID_PERFIL FOREIGN KEY (ID_PERFIL) REFERENCES PERFILES_CLIENTE(ID_PERFIL),
    CONSTRAINT FK_RESERVAS_ID_PLAN FOREIGN KEY (ID_PLAN) REFERENCES PLANES(ID_PLAN)
);

CREATE TABLE BOLETAS (
    ID_BOLETA NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    CODIGO VARCHAR2(100) NOT NULL UNIQUE,
    ESTADO VARCHAR2(30) NOT NULL,
    PRECIO_PAGADO NUMBER(12,2) NOT NULL,
    ID_RESERVA NUMBER(19) NOT NULL,
    ID_ZONA NUMBER(19),
    ID_TIPO_ENTRADA NUMBER(19),
    ID_COMBO NUMBER(19),
    CONSTRAINT FK_BOLETAS_ID_RESERVA FOREIGN KEY (ID_RESERVA) REFERENCES RESERVAS(ID_RESERVA),
    CONSTRAINT FK_BOLETAS_ID_ZONA FOREIGN KEY (ID_ZONA) REFERENCES ZONAS(ID_ZONA),
    CONSTRAINT FK_BOLETAS_ID_TIPO_ENTR FOREIGN KEY (ID_TIPO_ENTRADA) REFERENCES TIPOS_ENTRADA(ID_TIPO_ENTRADA),
    CONSTRAINT FK_BOLETAS_ID_COMBO FOREIGN KEY (ID_COMBO) REFERENCES COMBOS(ID_COMBO)
);

CREATE TABLE NOTIFICACIONES (
    ID_NOTIFICACION NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    ASUNTO VARCHAR2(200) NOT NULL,
    MENSAJE VARCHAR2(1000) NOT NULL,
    FECHA_HORA TIMESTAMP(6) NOT NULL,
    LEIDA NUMBER(1) NOT NULL,
    ID_USUARIO NUMBER(19) NOT NULL,
    ID_RESERVA NUMBER(19),
    CONSTRAINT FK_NOTIFICACIONE_ID_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES USUARIOS_SISTEMA(ID_USUARIO),
    CONSTRAINT FK_NOTIFICACIONE_ID_RESERVA FOREIGN KEY (ID_RESERVA) REFERENCES RESERVAS(ID_RESERVA)
);

ALTER TABLE ZONAS ADD CONSTRAINT CK_ZONAS_AFORO CHECK (AFORO > 0);
ALTER TABLE ZONAS ADD CONSTRAINT CK_ZONAS_PRECIO CHECK (PRECIO >= 0);
ALTER TABLE BOLETAS ADD CONSTRAINT CK_BOLETAS_PRECIO CHECK (PRECIO_PAGADO >= 0);
ALTER TABLE TIPOS_ENTRADA ADD CONSTRAINT CK_TIPO_DESCUENTO CHECK (PORCENTAJE_DESCUENTO BETWEEN 0 AND 100);
ALTER TABLE TIPOS_ENTRADA ADD CONSTRAINT CK_TIPO_ADULTO CHECK (REQUIERE_ADULTO IN (0,1) AND (ES_ADULTO IS NULL OR ES_ADULTO IN (0,1)));
ALTER TABLE NOTIFICACIONES ADD CONSTRAINT CK_NOTI_LEIDA CHECK (LEIDA IN (0,1));
ALTER TABLE COMBOS_ATRACCIONES ADD CONSTRAINT CK_COMBO_PORC CHECK (PORCENTAJE_PRECIO BETWEEN 0 AND 100);
ALTER TABLE COMBOS ADD CONSTRAINT CK_COMBO_DIAS CHECK (DIAS_VIGENCIA > 0);
ALTER TABLE FUNCIONES ADD CONSTRAINT CK_FUNCION_HORARIO CHECK (HORA_CIERRE > HORA_APERTURA);

CREATE INDEX IX_USUARIOS_SIS_ID_ROL ON USUARIOS_SISTEMA(ID_ROL);
CREATE INDEX IX_PRESTADORES_ID_MUNICIPIO ON PRESTADORES(ID_MUNICIPIO);
CREATE INDEX IX_PRESTADORES_ID_TIPO_PRES ON PRESTADORES(ID_TIPO_PRESTADOR);
-- IX_PERFILES_CLI_ID_USUARIO omitido: ID_USUARIO ya tiene índice único automático por UNIQUE
CREATE INDEX IX_PLANES_ID_PRESTADOR ON PLANES(ID_PRESTADOR);
CREATE INDEX IX_ATRACCIONES_ID_PRESTADOR ON ATRACCIONES(ID_PRESTADOR);
CREATE INDEX IX_FUNCIONES_ID_ATRACCION ON FUNCIONES(ID_ATRACCION);
CREATE INDEX IX_ZONAS_ID_FUNCION ON ZONAS(ID_FUNCION);
CREATE INDEX IX_RESERVAS_ID_PERFIL ON RESERVAS(ID_PERFIL);
CREATE INDEX IX_BOLETAS_ID_RESERVA ON BOLETAS(ID_RESERVA);
CREATE INDEX IX_BOLETAS_ID_ZONA ON BOLETAS(ID_ZONA);
CREATE INDEX IX_BOLETAS_ID_COMBO ON BOLETAS(ID_COMBO);
CREATE INDEX IX_NOTIFICACION_ID_USUARIO ON NOTIFICACIONES(ID_USUARIO);

